function Probe($url){
  try {
    $r=Invoke-WebRequest -Uri $url -Method GET -UseBasicParsing -TimeoutSec 8
    return "Status=$($r.StatusCode) len=$($r.Content.Length)"
  } catch {
    $e=$_.Exception
    if($e.Response){ return "Status=$($e.Response.StatusCode.value__) ($(($e.Response|Select-Object -ExpandProperty StatusDescription)) )" }
    return "ERROR: $($e.Message)"
  }
}
