& .\nginx.exe -t 2>&1 | ForEach-Object { if($_ -is [System.Management.Automation.ErrorRecord]){ $_.Exception.Message } else { $_ } }
& .\nginx.exe -s reload 2>&1 | Out-Null; Write-Host "reload rc=$LASTEXITCODE"

function Probe($m,$url,$body){
  try {
    $opt=@{ Uri=$url; Method=$m; UseBasicParsing=$true; TimeoutSec=8 }
    if($body){ $opt.Body=$body; $opt.ContentType='application/json' }
    $r=Invoke-WebRequest @opt
    return "Status=$($r.StatusCode) len=$($r.Content.Length) body=[$($r.Content.Substring(0,[Math]::Min(160,$r.Content.Length)))]"
  } catch {
    $e=$_.Exception
    if($e.Response){ $rs=$e.Response; $ct=''; try{$ct=$e.Response.GetResponseStream();}catch{}; return "Status=$($rs.StatusCode.value__) ($($rs.StatusDescription))" }
    return "ERROR: $($e.Message)"
  }
}
